m_L1T_config.init(m_L1T_config.m_config_string, FuncCachePreferNone);
m_L1C_config.init(m_L1C_config.m_config_string, FuncCachePreferNone);
m_L1D_config.init(m_L1D_config.m_config_string, FuncCachePreferNone);
